 * KnockoutJS Template Binding Error Debugger
 * 
 * Provides enhanced error messages for missing binding properties,
 * including typo suggestions based on Levenshtein distance.
 */

/**
 * Calculate the Levenshtein distance between two strings.
 * This is the minimum number of single-character edits
 * (insertions, deletions, or substitutions) required to change
 * one string into the other.
 *
 * @param {string} s1 - First string
 * @param {string} s2 - Second string
 * @returns {number} The Levenshtein distance
 */
function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Initialize base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,       // deletion
        dp[i][j - 1] + 1,       // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Create a debug helper for KnockoutJS binding errors.
 *
 * @param {Object} viewModel - The ViewModel object with properties
 * @returns {Object} A debug helper object with the diagnose method
 */
function createDebugHelper(viewModel) {
  const availableProperties = Object.keys(viewModel).sort();

  /**
   * Diagnose a missing property in a KnockoutJS binding.
   *
   * @param {string} propertyName - The property name that failed to bind
   * @returns {Object} Diagnostic information including suggestion
   */
  function diagnoseMissingProperty(propertyName) {
    const isAvailable = availableProperties.includes(propertyName);

    if (!isAvailable) {
      // Find closest matching property
      let closestMatch = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const dist = levenshteinDistance(propertyName, prop);
        if (dist <= 3) {
          if (dist < minDistance) {
            minDistance = dist;
            closestMatch = prop;
          } else if (dist === minDistance) {
            // Tie-breaker: alphabetical order (already sorted)
            if (prop < closestMatch) {
              closestMatch = prop;
            }
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: closestMatch
      };
    }

    // Property exists, no error
    return {
      error: false,
      missingProperty: null,
      availableProperties: availableProperties,
      suggestion: null
    };
  }

  return {
    vm: viewModel,
    properties: availableProperties,
    diagnose: diagnoseMissingProperty,
    diagnoseMissingProperty: diagnoseMissingProperty
  };
}

module.exports = {
  createDebugHelper,
  diagnoseMissingProperty: null, // Placeholder; use createDebugHelper instead
  levenshteinDistance
};"}

