{"command": "cat > /app/task_file/output/test-ko-debug.js << 'EOF'
/**
 * Test script for KnockoutJS Template Binding Error Debugger
 */

const { createDebugHelper, levenshteinDistance } = require('./ko-debug');

// Define a sample ViewModel
const sampleViewModel = {
  items: ['item1', 'item2', 'item3'],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 42
};

// Create debug helper
const debugHelper = createDebugHelper(sampleViewModel);

let passed = 0;
let failed = 0;

function assert(condition, testName) {
  if (condition) {
    console.log('PASS: ' + testName);
    passed++;
  } else {
    console.log('FAIL: ' + testName);
    failed++;
  }
}

// Test 1: Diagnose missing property "item" (should suggest "items")
console.log('\n--- Test Suite: KnockoutJS Binding Error Debugger ---');
console.log('\nViewModel properties:', debugHelper.properties.join(', '));

const result1 = debugHelper.diagnoseMissingProperty('item');
assert(result1.error === true, 'Test 1: Missing property "item" should have error=true');
assert(result1.missingProperty === 'item', 'Test 1: missingProperty should be "item"');
assert(result1.suggestion === 'items', 'Test 1: should suggest "items" for "item"');
assert(result1.availableProperties.length === 5, 'Test 1: should have 5 available properties');
assert(JSON.stringify(result1.availableProperties) === JSON.stringify(['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount']), 'Test 1: availableProperties should be alphabetically sorted');

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
const result2 = debugHelper.diagnoseMissingProperty('selctedItem');
assert(result2.error === true, 'Test 2: Missing property "selctedItem" should have error=true');
assert(result2.missingProperty === 'selctedItem', 'Test 2: missingProperty should be "selctedItem"');
assert(result2.suggestion === 'selectedItem', 'Test 2: should suggest "selectedItem" for "selctedItem"');

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
const result3 = debugHelper.diagnoseMissingProperty('completelyWrong');
assert(result3.error === true, 'Test 3: Missing property "completelyWrong" should have error=true');
assert(result3.missingProperty === 'completelyWrong', 'Test 3: missingProperty should be "completelyWrong"');
assert(result3.suggestion === null, 'Test 3: should have null suggestion for "completelyWrong"');

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
const result4 = debugHelper.diagnoseMissingProperty('isLoad');
assert(result4.error === true, 'Test 4: Missing property "isLoad" should have error=true');
assert(result4.missingProperty === 'isLoad', 'Test 4: missingProperty should be "isLoad"');
assert(result4.suggestion === 'isLoading', 'Test 4: should suggest "isLoading" for "isLoad"');

// Additional Levenshtein distance tests
console.log('\n--- Additional: Levenshtein Distance Tests ---');
assert(levenshteinDistance('item', 'items') === 1, 'Levenshtein("item", "items") === 1');
assert(levenshteinDistance('selctedItem', 'selectedItem') === 1, 'Levenshtein("selctedItem", "selectedItem") === 1');
assert(levenshteinDistance('isLoad', 'isLoading') === 2, 'Levenshtein("isLoad", "isLoading") === 2');
assert(levenshteinDistance('hello', 'hello') === 0, 'Levenshtein("hello", "hello") === 0');
assert(levenshteinDistance('abc', '') === 3, 'Levenshtein("abc", "") === 3');

// Test that an existing property returns no error
const resultExisting = debugHelper.diagnoseMissingProperty('items');
assert(resultExisting.error === false, 'Existing property "items" should have error=false');
assert(resultExisting.missingProperty === null, 'Existing property should have missingProperty=null');
assert(resultExisting.suggestion === null, 'Existing property should have suggestion=null');

// Summary
console.log('\n--- Summary ---');
console.log('Passed: ' + passed);
console.log('Failed: ' + failed);

if (failed > 0) {
  process.exit(1);
} else {
  console.log('\nAll tests passed!');
  process.exit(0);
}
EOF"}

